const MARS_SPHERICAL_RADIUS_KM = 3396.19;

interface LocationAreaSpec {
  semiMajorKm: number;
  semiMinorKm: number;
  azimuthDeg: number;
  dimensionLabel: string;
  isPolarCap?: boolean;
  wktAreaKm2?: number;
}

export interface LocationAreaInfo {
  id: string;
  name: string;
  areaKm2: number;
  dimensionLabel: string;
  radiusKm: number;
  ringLonLat: Array<[number, number]>;
  isWktExact: boolean;
  isPolarCap: boolean;
  polarCenterLatDeg?: number;
}

