function generateGeodesicEllipseRing(
  centerLatDeg: number,
  centerLonDeg: number,
  semiMajorKm: number,
  semiMinorKm: number,
  azimuthDeg: number,
  steps = 64
): Array<[number, number]> {
  const lat0 = (centerLatDeg * Math.PI) / 180;
  const lon0 = (centerLonDeg * Math.PI) / 180;
  const azRad = (azimuthDeg * Math.PI) / 180;
  const ring: Array<[number, number]> = [];

  for (let i = 0; i <= steps; i++) {
    const theta = (i / steps) * Math.PI * 2;
    const xLocal = semiMajorKm * Math.cos(theta);
    const yLocal = semiMinorKm * Math.sin(theta);
    const northKm = xLocal * Math.cos(azRad) - yLocal * Math.sin(azRad);
    const eastKm = xLocal * Math.sin(azRad) + yLocal * Math.cos(azRad);
    const distKm = Math.hypot(northKm, eastKm);
    const brng = Math.atan2(eastKm, northKm);
    const angDist = distKm / MARS_SPHERICAL_RADIUS_KM;

    const sinLat =
      Math.sin(lat0) * Math.cos(angDist) +
      Math.cos(lat0) * Math.sin(angDist) * Math.cos(brng);
    const lat = Math.asin(Math.max(-1, Math.min(1, sinLat)));
    const lon =
      lon0 +
      Math.atan2(
        Math.sin(brng) * Math.sin(angDist) * Math.cos(lat0),
        Math.cos(angDist) - Math.sin(lat0) * Math.sin(lat)
      );

    const clampedLat = Math.max(-89.2, Math.min(89.2, (lat * 180) / Math.PI));
    let wrappedLon = ((lon * 180) / Math.PI) % 360;
    if (wrappedLon > 180) wrappedLon -= 360;
    if (wrappedLon < -180) wrappedLon += 360;
    ring.push([Number(wrappedLon.toFixed(4)), Number(clampedLat.toFixed(4))]);
  }
  return ring;
}

function generatePolarCapBoundaryRing(isNorth: boolean, radiusKm: number, steps = 72): Array<[number, number]> {
  const edgeOffsetDeg = (radiusKm / MARS_SPHERICAL_RADIUS_KM) * (180 / Math.PI);
  const edgeLat = isNorth ? 90 - edgeOffsetDeg : -90 + edgeOffsetDeg;
  const ring: Array<[number, number]> = [];
  for (let i = 0; i <= steps; i++) {
    const lon = -180 + (i / steps) * 360;
    ring.push([Number(lon.toFixed(3)), Number(edgeLat.toFixed(4))]);
  }
  return ring;
}

export function formatLocationAreaKm2(areaKm2: number): string {
  if (areaKm2 < 10) return `${areaKm2.toFixed(2)} km²`;
  if (areaKm2 < 1000) return `${Math.round(areaKm2).toLocaleString('en-US')} km²`;
  return `${Math.round(areaKm2).toLocaleString('en-US')} km²`;
}

export function getLocationAreaInfo(target: MarsTarget): LocationAreaInfo | null {
  if (target.category !== 'landmark') return null;

  const spec = LOCATION_AREA_SPECS[target.id] ?? {
    semiMajorKm: 60,
    semiMinorKm: 60,
    azimuthDeg: 0,
    dimensionLabel: '120 km nominal region',
  };

  const wktOutline = MARS_FEATURE_OUTLINES[target.id as keyof typeof MARS_FEATURE_OUTLINES];
  const areaKm2 = spec.wktAreaKm2 ?? Math.PI * spec.semiMajorKm * spec.semiMinorKm;

  if (wktOutline) {
    return {
      id: target.id,
      name: wktOutline.name,
      areaKm2,
      dimensionLabel: spec.dimensionLabel,
      radiusKm: Math.max(spec.semiMajorKm, spec.semiMinorKm),
      ringLonLat: wktOutline.ringLonLat.map(([lon, lat]) => [lon, lat]),
      isWktExact: true,
      isPolarCap: false,
    };
  }

  if (spec.isPolarCap) {
    const isNorth = target.latitude >= 0;
    return {
      id: target.id,
      name: target.name,
      areaKm2,
      dimensionLabel: spec.dimensionLabel,
      radiusKm: spec.semiMajorKm,
      ringLonLat: generatePolarCapBoundaryRing(isNorth, spec.semiMajorKm),
      isWktExact: false,
      isPolarCap: true,
      polarCenterLatDeg: isNorth ? 89.95 : -89.95,
    };
  }

  return {
    id: target.id,
    name: target.name,
    areaKm2,
    dimensionLabel: spec.dimensionLabel,
    radiusKm: Math.max(spec.semiMajorKm, spec.semiMinorKm),
    ringLonLat: generateGeodesicEllipseRing(
      target.latitude,
      target.longitude,
      spec.semiMajorKm,
      spec.semiMinorKm,
      spec.azimuthDeg
    ),
    isWktExact: false,
    isPolarCap: false,
  };
}

